#include<iostream>
#include<vector>
#include<string>
#include <utility> 
#include <sstream>
#include<algorithm> 
#include<cmath>
#include<map>
using namespace std;
​
int main() {
    // 处理输入
    int n,k,l;
    cin >> n >> k >> l;
    vector<int> nums(n);
    for (int i = 0; i < n; i++) {
        cin >> nums[i];
    }

    for (int i = 0; i <l; i++) {
        string command;
        int arg1, arg2;
        cin >> command >> arg1 >> arg2;
        // 分情况处理
        if (command == "Add") {
            int index = arg1 -1;
            nums[index] += arg2;
        } else if (command == "Sub") {
            int index = arg1 - 1;
            // 保证营地数量不小于0
            nums[index] = max(0, nums[index] - arg2);
        } else {
            int start = arg1 -1, end = arg2 - 1;
            // 滑动窗口求最小值
            int currentSum = 0;
            for (int j = start; j < start + k;j++) {
                currentSum += nums[j];
            }
            int minSum = currentSum;
            for (int idx = start + 1; idx <= end - k + 1; idx++) {
                currentSum = currentSum - nums[idx - 1] + nums[idx + k - 1];
                minSum = min(minSum, currentSum);
            }
            cout << minSum << endl;
        }
    }
    return 0;
}

