package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
    // 设置最大缓冲区，比如 1MB
    buf := make([]byte, 0, 1024*1024)
    scanner.Buffer(buf, 1024*1024)

    // 读取第一行 N K L
    scanner.Scan()
    firstLine := strings.Fields(scanner.Text())
    n, _ := strconv.Atoi(firstLine[0])
    k, _ := strconv.Atoi(firstLine[1])
    l, _ := strconv.Atoi(firstLine[2])
​
    // 读取第二行 N 个营地人数
    scanner.Scan()
    numStr := strings.Fields(scanner.Text())
    nums := make([]int, n)
    for i := 0; i < n; i++ {
        nums[i], _ = strconv.Atoi(numStr[i])
    }
​
    // 处理接下来的 L 条命令
    for i := 0; i < l; i++ {
        scanner.Scan()
        cmd := strings.Fields(scanner.Text())
        command := cmd[0]
        arg1, _ := strconv.Atoi(cmd[1])
        arg2, _ := strconv.Atoi(cmd[2])
​
        if command == "Add" {
            // 增加人数
            nums[arg1-1] += arg2
        } else if command == "Sub" {
            // 保证人数不小于0
            if nums[arg1-1] < arg2 {
                nums[arg1-1] = 0
            } else {
                nums[arg1-1] -= arg2
            }
        } else if command == "Query" {
            // 查询连续 K 个营地人数最小和
            start := arg1 - 1
            end := arg2 - 1
            currentSum := 0
            // 初始化滑动窗口
            for j := start; j < start+k; j++ {
                currentSum += nums[j]
            }
            minSum := currentSum
            // 滑动窗口求最小值
            for idx := start + 1; idx <= end-k+1; idx++ {
                currentSum = currentSum - nums[idx-1] + nums[idx+k-1]
                if currentSum < minSum {
                    minSum = currentSum
                }
            }
            fmt.Println(minSum)
        }
    }
}
